from collections import Counter
cells={(r,c) for r,row in enumerate(['.##.##.','######.','.##.#..','..###..']) for c,x in enumerate(row) if x=='#'}
# placements square, L triomino orientations keyed by missing corner in bounding 2x2
placements=[]
for r in range(4):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: placements.append(('sq',None,sq))
  box={(r+i,c+j) for i in range(2) for j in range(2)}
  for miss in box:
   sh=box-{miss}
   if sh<=cells: placements.append(('L',(miss[0]-r,miss[1]-c),sh))
sol=[]
def rec(rem, chosen, nsq):
 if not rem:
  if nsq==1: sol.append(chosen)
  return
 x=min(rem)
 for typ,ori,sh in placements:
  if x in sh and sh<=rem and (typ!='sq' or nsq<1):
   rec(rem-sh,chosen+[(typ,ori,sh)],nsq+(typ=='sq'))
rec(cells,[],0)
print(len(sol))
for s in sol[:5]:
 print([(t,o,sorted(x)) for t,o,x in s])
